          text: 'Imaan immediately knew she had stepped somewhere sensitive.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 59799),
          end: Duration(milliseconds: 62408),
          text: '"You do not have to answer," she said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 62934),
          end: Duration(milliseconds: 66832),
          text: 'Rayyan ran his thumb along the worn edge of the cover.',
        ),
        CaptionLine(
