        CaptionLine(
          start: Duration(milliseconds: 77996),
          end: Duration(milliseconds: 81510),
          text: 'This time neither of them asked another question.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 81638),
          end: Duration(milliseconds: 87558),
          text:
              'Instead, Akhlaaq picked up a twig and drew three crooked circles in the dust.',
