        CaptionLine(
          start: Duration(milliseconds: 103506),
          end: Duration(milliseconds: 110206),
          text:
              '"I wanted to understand," Imaan said, "but I think my question made him uncomfortable."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 110506),
          end: Duration(milliseconds: 111106),
          text: 'Ammi nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 111106),
          end: Duration(milliseconds: 115606),
          text: '"A kind person learns two things that can seem opposite.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 115606),
          end: Duration(milliseconds: 119312),
          text: 'Sometimes kindness means giving a person privacy.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 119312),
          end: Duration(milliseconds: 127814),
          text:
              'Sometimes, when there are signs that someone may be unsafe, kindness means asking carefully and seeking help.',
