        CaptionLine(
          start: Duration(milliseconds: 127814),
          end: Duration(milliseconds: 130574),
          text: 'Wisdom is knowing which moment you are in."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 130574),
          end: Duration(milliseconds: 132074),
          text: '"How do I know?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 132074),
          end: Duration(milliseconds: 133234),
          text: '"You listen.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 133234),
          end: Duration(milliseconds: 135334),
          text: 'You notice patterns.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 135334),
          end: Duration(milliseconds: 141534),
          text:
