        ),
        CaptionLine(
          start: Duration(milliseconds: 141542),
          end: Duration(milliseconds: 144142),
          text: 'You speak to a trustworthy adult."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 144464),
          end: Duration(milliseconds: 152502),
          text:
              'Imaan thought about Rayyan\'s quick silences, his tiredness, and the way he always looked towards the park gate before sunset.',
        ),
