          end: Duration(milliseconds: 207246),
          text: 'Its wing did not seem right.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 207246),
          end: Duration(milliseconds: 209946),
          text: 'He did not try to grab it immediately.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 209946),
          end: Duration(milliseconds: 213946),
          text: 'Instead he asked an adult caretaker for help.',
        ),
