        ),
        CaptionLine(
          start: Duration(milliseconds: 220446),
          end: Duration(milliseconds: 221414),
          text: 'Akhlaaq looked impressed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 221414),
          end: Duration(milliseconds: 224054),
          text: '"You did not just pick it up."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 224537),
          end: Duration(milliseconds: 225694),
          text: 'Rayyan shook his head.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 225694),
          end: Duration(milliseconds: 229494),
          text: '"I wanted to help, but I did not know the safe way."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 230070),
          end: Duration(milliseconds: 230934),
          text: 'Imaan smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 230934),
          end: Duration(milliseconds: 232854),
          text: '"Kindness with wisdom."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 233317),
          end: Duration(milliseconds: 234334),
          text: 'Rayyan looked at her.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 234934),
          end: Duration(milliseconds: 236254),
          text: '"Zameer says that too."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 236254),
          end: Duration(milliseconds: 240254),
          text: '"He is stealing Ammi\'s material," Akhlaaq whispered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 241382),
          end: Duration(milliseconds: 245622),
          text:
              'That evening, before leaving, Rayyan said something he had never said before.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 246422),
          end: Duration(milliseconds: 248022),
          text: '"I am used to being alone."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 249604),
          end: Duration(milliseconds: 250988),
          text: 'Imaan did not ask why.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 251795),
          end: Duration(milliseconds: 254102),
          text: 'Akhlaaq did not try to make a joke.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 255519),
          end: Duration(milliseconds: 257782),
          text: 'Rayyan looked from one sibling to the other.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 258742),
          end: Duration(milliseconds: 262436),
          text: '"But I do not think I want to be used to it forever."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 262918),
          end: Duration(milliseconds: 263642),
          text: 'Imaan smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 263642),
          end: Duration(milliseconds: 265571),
          text: '"You do not have to be."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 266295),
          end: Duration(milliseconds: 268465),
          text: 'Akhlaaq held out the football.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 268465),
          end: Duration(milliseconds: 269430),
          text: '"Tomorrow?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 270640),
          end: Duration(milliseconds: 272690),
          text: 'Rayyan looked at it, then nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 272690),
          end: Duration(milliseconds: 273510),
          text: '"Tomorrow."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 273510),
          end: Duration(milliseconds: 281318),
          text: 'CHALLENGE OF THE DAY 3: Kindness in Listening',
        ),
        CaptionLine(
          start: Duration(milliseconds: 281318),
          end: Duration(milliseconds: 290298),
          text:
              'Your mission: Have one conversation today in which you let the other person finish without interrupting or asking questions they do not want to answer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 290298),
          end: Duration(milliseconds: 297458),
          text:
              'Quick reflection: Did I listen to understand, or only wait for my turn to speak?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 297458),
          end: Duration(milliseconds: 308249),
          text:
              'Level-Up: Notice one moment when silence is kinder than another question, and one moment when a gentle question may help someone feel supported.',
        ),
      ],
    ),
    Story(
