        CaptionLine(
          start: Duration(milliseconds: 83869),
          end: Duration(milliseconds: 86909),
          text: '"Then I am sharing too."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 86909),
          end: Duration(milliseconds: 90529),
          text: '"Perfect," Imaan said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 90529),
          end: Duration(milliseconds: 92869),
          text: 'No one counted who had brought more.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 93713),
          end: Duration(milliseconds: 100157),
          text:
              'Akhlaaq later whispered to Imaan, "That felt different from giving him food."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 100157),
