        CaptionLine(
          start: Duration(milliseconds: 317920),
          end: Duration(milliseconds: 325072),
          text:
              'Quick reflection: Did my kindness make the other person feel included or singled out?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 325072),
          end: Duration(milliseconds: 331585),
          text:
              'Level-Up: Ask yourself how you can help in a way that allows the other person to contribute too.',
        ),
      ],
