        ),
        CaptionLine(
          start: Duration(milliseconds: 115051),
          end: Duration(milliseconds: 118599),
          text: 'At school Rayyan stopped just inside the gate.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 118599),
          end: Duration(milliseconds: 124256),
          text:
              'He looked at the classrooms, reading corner and rows of children\'s artwork.',
