        CaptionLine(
          start: Duration(milliseconds: 148779),
          end: Duration(milliseconds: 151004),
          text: 'Rayyan\'s smile disappeared.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151004),
          end: Duration(milliseconds: 154364),
          text: 'Before Sheikh Uncle could reach them, Imaan turned around.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 154364),
          end: Duration(milliseconds: 157484),
          text: '"That is not kind," she said firmly.',
