        CaptionLine(
          start: Duration(milliseconds: 173149),
          end: Duration(milliseconds: 175736),
          text: 'Sheikh Uncle had heard enough to understand.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 175736),
          end: Duration(milliseconds: 178572),
          text: 'He joined them without raising his voice.',
