          text: 'Imaan smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 237556),
          end: Duration(milliseconds: 240524),
          text: '"You really want to study, do you not?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 240524),
          end: Duration(milliseconds: 243324),
          text: 'This time Rayyan did not close up.',
