        CaptionLine(
          start: Duration(milliseconds: 292669),
          end: Duration(milliseconds: 296753),
          text: 'Tomorrow he will think he can choose his own life."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 296753),
          end: Duration(milliseconds: 300428),
          text: 'Kamran stared at the unopened chocolate on the table.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 300428),
          end: Duration(milliseconds: 303608),
          text:
              'For a brief moment, he remembered that Rayyan had saved it for him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 303608),
          end: Duration(milliseconds: 305948),
          text: 'Then he pushed the thought away.',
