        CaptionLine(
          start: Duration(milliseconds: 305948),
          end: Duration(milliseconds: 311028),
          text: 'The next day Rayyan was not allowed to go to the park.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 311028),
          end: Duration(milliseconds: 320388),
          text:
