        CaptionLine(
          start: Duration(milliseconds: 329296),
          end: Duration(milliseconds: 334056),
          text: 'Yet one good day had given him something new.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 334056),
          end: Duration(milliseconds: 336596),
          text: 'Hope.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 336596),
          end: Duration(milliseconds: 340096),
          text: 'CHALLENGE OF THE DAY 5: Kind Words Day',
        ),
        CaptionLine(
          start: Duration(milliseconds: 340364),
          end: Duration(milliseconds: 351564),
          text:
              'Your mission: Use your words to make at least three people feel respected or welcomed today. If you notice teasing or exclusion, respond calmly without humiliating anyone.',
