    Story(
      id: 'kindness_en_10',
      title: 'Ep 10 · The Kindness That Came Back',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/kindness.webp',
      audioAsset: 'assets/audio/en/kindness/10_the_kindness_that_came_back.ogg',
      category: StoryCategory.moral,
      description: 'The Kindness That Came Back — episode 10 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 201),
          end: Duration(milliseconds: 3058),
          text: 'Chapter Ten: The Kindness That Came Back',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3058),
          end: Duration(milliseconds: 4808),
          text: 'Several weeks passed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 5294),
          end: Duration(milliseconds: 6947),
          text: 'Rayyan settled into school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 6947),
          end: Duration(milliseconds: 17429),
          text:
              'He still loved the reading corner most, but he had also discovered that Akhlaaq was right about homework being less exciting than the idea of homework.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 17429),
          end: Duration(milliseconds: 21909),
          text: '"You promised you would do it happily," Akhlaaq reminded him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 21909),
          end: Duration(milliseconds: 24637),
          text: '"I was young and inexperienced."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 25219),
          end: Duration(milliseconds: 26237),
          text: 'Imaan laughed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 26237),
          end: Duration(milliseconds: 28317),
          text: '"It has been three weeks."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 29044),
          end: Duration(milliseconds: 29917),
          text: 'Rayyan smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 29917),
          end: Duration(milliseconds: 34537),
          text:
              'He had begun to sound like someone who expected to have a tomorrow.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 34537),
          end: Duration(milliseconds: 38157),
          text: 'One afternoon Sheikh Uncle spoke to him privately.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 38157),
          end: Duration(milliseconds: 40845),
          text: '"Your uncle has been asking for a chance to apologise.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 41557),
          end: Duration(milliseconds: 47245),
          text:
              'The adults responsible for your care believe a short supervised meeting can be arranged if you want one.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 47245),
          end: Duration(milliseconds: 49205),
          text: 'You may also say no."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 50112),
          end: Duration(milliseconds: 52108),
          text: 'Rayyan became quiet.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 52108),
          end: Duration(milliseconds: 56643),
          text: '"If I meet him, do I have to go back?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 56643),
          end: Duration(milliseconds: 57006),
          text: '"No."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 57006),
          end: Duration(milliseconds: 61978),
          text: '"If I forgive him, do I have to trust him?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 61978),
          end: Duration(milliseconds: 66573),
          text: '"No. Forgiveness, trust and safety are different things.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 66573),
          end: Duration(milliseconds: 69632),
          text: 'Trust is rebuilt by consistent behaviour."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 71198),
          end: Duration(milliseconds: 73573),
          text: 'Rayyan thought for a long time.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 73573),
          end: Duration(milliseconds: 75573),
          text: '"I want to hear what he says."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 75573),
          end: Duration(milliseconds: 81573),
          text:
              'The meeting took place at the school office with Sheikh Uncle and a responsible adult present.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 81573),
          end: Duration(milliseconds: 90545),
          text:
              'Uncle Kamran looked different, not because of his clothes, but because the confidence that once filled every sentence was gone.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 90545),
          end: Duration(milliseconds: 93855),
          text: 'For a moment neither of them spoke.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 93855),
          end: Duration(milliseconds: 99139),
          text:
              'Then Kamran said, "Rayyan, I frightened you when I was supposed to protect you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 99139),
          end: Duration(milliseconds: 102509),
          text: 'I stopped you from learning because I wanted control.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 102509),
          end: Duration(milliseconds: 105935),
          text: 'I hurt you and then called it discipline.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 105935),
          end: Duration(milliseconds: 106869),
          text: 'I was wrong."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 107386),
          end: Duration(milliseconds: 109349),
          text: 'Rayyan looked at him silently.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 109975),
          end: Duration(milliseconds: 116309),
          text:
              'Kamran continued, "Mutakabbir encouraged my pride, but he did not make my choices for me.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 116309),
          end: Duration(milliseconds: 120629),
          text: 'I listened because his words suited what I wanted to believe.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 120629),
          end: Duration(milliseconds: 124797),
          text: 'I am responsible for what I did."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 125368),
          end: Duration(milliseconds: 127197),
          text: 'Sheikh Uncle said nothing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 127987),
          end: Duration(milliseconds: 129437),
          text: 'Kamran took a breath.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 129437),
          end: Duration(milliseconds: 135117),
          text:
              '"You do not owe me forgiveness, and you do not have to come back to my house.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 135117),
          end: Duration(milliseconds: 140037),
          text:
              'I only wanted you to know that I am trying to change what I can."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 140517),
          end: Duration(milliseconds: 145112),
          text:
              'Rayyan\'s eyes filled with tears, but his voice remained steady.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 145112),
          end: Duration(milliseconds: 148312),
          text: '"I do not want to hate you, Uncle Kamran.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 148312),
          end: Duration(milliseconds: 151216),
          text: 'I can forgive you for the sake of Allah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151686),
          end: Duration(milliseconds: 154861),
          text: 'But I am not ready to trust you yet."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 154861),
          end: Duration(milliseconds: 156272),
          text: 'Kamran nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 156272),
          end: Duration(milliseconds: 157565),
          text: '"I understand."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 157565),
          end: Duration(milliseconds: 158285),
          text: 'Rayyan looked at him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 158285),
          end: Duration(milliseconds: 163585),
          text:
              '"If you are really changing, keep changing even if I do not see it."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 163585),
          end: Duration(milliseconds: 168509),
          text: 'For the first time, Kamran gave a small, humble smile.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 168509),
          end: Duration(milliseconds: 169447),
          text: '"I will try."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 169447),
          end: Duration(milliseconds: 172091),
          text: 'There was no dramatic embrace.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 172091),
          end: Duration(milliseconds: 175281),
          text: 'No promise that everything was fixed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 175281),
          end: Duration(milliseconds: 180893),
          text:
              'The meeting ended quietly, and Rayyan returned to Khala Hira\'s home.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 180893),
          end: Duration(milliseconds: 186181),
          text:
              'A month later, several boxes arrived at the Amanpur school library.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 186181),
          end: Duration(milliseconds: 192281),
          text:
              'They contained storybooks, beginner science books and notebooks for children who needed them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 192281),
          end: Duration(milliseconds: 194492),
          text: 'A short note was attached.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 194492),
          end: Duration(milliseconds: 197441),
          text: '"For every child who wants to learn.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 197441),
          end: Duration(milliseconds: 201481),
          text:
              'No child should be made to feel that knowledge is not meant for them."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 204389),
          end: Duration(milliseconds: 206429),
          text: 'Rayyan recognised the handwriting.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 207224),
          end: Duration(milliseconds: 209609),
          text: 'Akhlaaq peered over his shoulder.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 209609),
          end: Duration(milliseconds: 212069),
          text: '"Do you know who sent them?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 212684),
          end: Duration(milliseconds: 216069),
          text: 'Rayyan folded the note carefully.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 216069),
          end: Duration(milliseconds: 219749),
          text: '"I think someone is learning too."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 219749),
          end: Duration(milliseconds: 225437),
          text:
              'That afternoon, the three friends returned to the park where everything had begun.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 225437),
          end: Duration(milliseconds: 229037),
          text: 'The orange cat was asleep beneath the old bench.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 229037),
          end: Duration(milliseconds: 230997),
          text: 'Children were playing football nearby.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 230997),
          end: Duration(milliseconds: 235837),
          text:
              'A new boy stood alone near the gate, clutching a book to his chest.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 236266),
          end: Duration(milliseconds: 237877),
          text: 'Imaan noticed him first.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 238597),
          end: Duration(milliseconds: 240037),
          text: 'Akhlaaq looked at Rayyan.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 240037),
          end: Duration(milliseconds: 242317),
          text: '"Should we go and ask him seventeen questions?"',
        ),
        CaptionLine(
          start: Duration(milliseconds: 243785),
          end: Duration(milliseconds: 245285),
          text: 'Imaan gave him a look.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 245985),
          end: Duration(milliseconds: 246965),
          text: 'Rayyan laughed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 246965),
          end: Duration(milliseconds: 251483),
          text:
              'Then he walked towards the boy, stopped at a respectful distance and said, "Assalam o Alaikum.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 253085),
          end: Duration(milliseconds: 255165),
          text: 'You can sit with us if you want."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 255165),
          end: Duration(milliseconds: 256645),
          text: 'The boy looked uncertain.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 256645),
          end: Duration(milliseconds: 259325),
          text: '"You do not have to talk," Rayyan added.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 259325),
          end: Duration(milliseconds: 261085),
          text: '"You can just sit."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 261085),
          end: Duration(milliseconds: 264253),
          text: 'A small smile appeared on the boy\'s face.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 264253),
          end: Duration(milliseconds: 265253),
          text: '"Wa Alaikum Assalam.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 265253),
          end: Duration(milliseconds: 266253),
          text: 'Okay."',
        ),
        CaptionLine(
          start: Duration(milliseconds: 266253),
          end: Duration(milliseconds: 268693),
          text: 'They returned to the bench together.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 269000),
          end: Duration(milliseconds: 270533),
          text: 'Imaan opened her drawing book.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 271080),
          end: Duration(milliseconds: 274453),
          text: 'Akhlaaq tried once again to balance a leaf on his nose.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 274453),
          end: Duration(milliseconds: 279373),
          text:
              'Rayyan opened his storybook and moved slightly to make room for the new boy.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 279373),
          end: Duration(milliseconds: 281653),
          text: 'No one announced what they were doing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 281653),
          end: Duration(milliseconds: 282173),
          text: 'No one asked for praise.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 282221),
          end: Duration(milliseconds: 284221),
          text: 'The kindness simply continued.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 284221),
          end: Duration(milliseconds: 290221),
          text:
              'Rayyan had learned that kindness did not mean accepting cruelty.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 290628),
          end: Duration(milliseconds: 296221),
          text:
              'Imaan had learned that kindness needed wisdom, not only good intentions.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 296898),
          end: Duration(milliseconds: 303724),
          text:
              'Akhlaaq had learned that friendship sometimes required serious courage, not only laughter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 303724),
          end: Duration(milliseconds: 310069),
          text:
              'Uncle Kamran had learned that power without mercy was not strength at all.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 310069),
          end: Duration(milliseconds: 315249),
          text: 'And all of them had learned the same truth in different ways:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 315249),
          end: Duration(milliseconds: 317469),
          text: 'Kindness is not weakness.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 317469),
          end: Duration(milliseconds: 320589),
          text: 'Sometimes kindness notices.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 320589),
          end: Duration(milliseconds: 324157),
          text: 'Sometimes it listens.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 324157),
          end: Duration(milliseconds: 326397),
          text: 'Sometimes it shares.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 326397),
          end: Duration(milliseconds: 328717),
          text: 'Sometimes it protects.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 328717),
          end: Duration(milliseconds: 333997),
          text:
              'Sometimes it forgives without pretending trust is instantly restored.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 333997),
          end: Duration(milliseconds: 340837),
          text:
              'And sometimes one small act of kindness becomes the beginning of a completely different life.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 342125),
          end: Duration(milliseconds: 347125),
          text: 'CHALLENGE OF THE DAY 10: Pass Kindness Forward',
        ),
        CaptionLine(
          start: Duration(milliseconds: 347125),
          end: Duration(milliseconds: 355445),
          text:
              'Your mission: Choose one kindness you received from someone else and pass a similar kindness to another person this week.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 355445),
          end: Duration(milliseconds: 361245),
          text:
              'Quick reflection: How did someone else\'s kindness change what I chose to do?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 361245),
          end: Duration(milliseconds: 373453),
          text:
              'Level-Up: Make a seven-day kindness promise: notice, listen, include, share, speak gently, protect wisely and help without seeking praise.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 373453),
          end: Duration(milliseconds: 375297),
          text: 'Islamic Reference Notes',
        ),
        CaptionLine(
          start: Duration(milliseconds: 375297),
          end: Duration(milliseconds: 382061),
          text:
              'These references support the Islamic themes woven naturally through the story.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 382061),
          end: Duration(milliseconds: 388381),
          text:
              'The child-facing narrative uses brief paraphrases rather than long quotations.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 389521),
          end: Duration(milliseconds: 399461),
          text:
              'Qur\'an 16:90: Allah commands justice and excellence/kindness (ihsan), and forbids wrongdoing and oppression.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 399461),
          end: Duration(milliseconds: 408249),
          text:
              'Sahih Muslim: The Prophet Muhammad, peace and blessings be upon him, taught that every good deed is charity.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 408249),
          end: Duration(milliseconds: 418529),
          text:
              'Sahih al-Bukhari and Sahih Muslim: The Prophet taught that whoever believes in Allah and the Last Day should speak good or remain silent.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 418529),
          end: Duration(milliseconds: 428377),
          text:
              'Sahih al-Bukhari and Sahih Muslim: Authentic hadith teach that mercy shown to a thirsty animal can be a cause of Allah\'s forgiveness.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 428377),
          end: Duration(milliseconds: 437277),
          text:
              'Sahih Muslim: Allah is gentle and loves gentleness, and gentleness brings goodness that harshness does not.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 437277),
          end: Duration(milliseconds: 447965),
          text:
              'Jami\' at-Tirmidhi / Sunan Abi Dawud: The merciful are shown mercy by the Most Merciful; believers are encouraged to show mercy to those on earth.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 447965),
          end: Duration(milliseconds: 455965),
          text:
              'Key safeguarding message: Kindness never requires a child to remain in danger or keep harmful secrets.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 455965),
          end: Duration(milliseconds: 461965),
          text:
              'When someone may be unsafe, speaking to a trustworthy adult is an act of care and courage.',
        ),
      ],
    ),
  ],
);
